const VALIDITY_STATUS = {
  troodon: {
    status: 'nomen_dubium',
    note: 'Troodon formosus was established on isolated serrated teeth from the Judith River Formation. The teeth are diagnostic but cannot be assigned to specific skeletal material with confidence; specimens formerly referred to Troodon are now attributed to Stenonychosaurus, Latenivenatrix and other genera. The name Troodon itself is therefore a nomen dubium — a "doubtful name" lacking a type specimen that anchors it to a complete animal.'
  },
  torosaurus: {
    status: 'contested',
    note: 'Scannella and Horner (2010) proposed that Torosaurus represents fully mature Triceratops individuals in which the frill fenestrae develop late in ontogeny — effectively synonymising the two genera. Most subsequent analyses (Longrich and Field 2012, and others) reject this, pointing to consistent morphological differences independent of growth stage, and maintain Torosaurus as a valid distinct genus. The debate is ongoing.'
  },
  alioramus: {
    status: 'contested',
    note: 'The gracile skull and lower tooth count of Alioramus have led some researchers to suggest it may represent a juvenile or female Tarbosaurus rather than a distinct genus. Novas and colleagues (2009) and subsequent phylogenetic analyses recover Alioramus as a valid tyrannosaurid, but the juvenile hypothesis retains some support and has not been definitively ruled out.'
  },

  irritator: {
    status: 'contested',
    note: 'The holotype skull (SMNS 58022) was heavily reconstructed with non-fossil plaster by commercial preparators before it reached scientific study. An estimated portion of the skull was artificially extended to make it appear more complete for the fossil market. This means some anatomical details described from the holotype — including aspects of the skull proportions — may be artefactual rather than biological. The genus Irritator is broadly accepted, but the reliability of certain described features has been questioned since the artificial preparation was identified by Martill, Cruickshank and colleagues in 1996.'
  },

  gasparinisaura: {
    status: 'contested',
    note: 'The phylogenetic placement of Gasparinisaura within Ornithopoda is highly unstable across published analyses — it has been recovered in significantly different positions in different cladistic studies, ranging from near the base of Ornithopoda to more derived positions. This instability suggests the taxon may be insufficiently diagnosed by unique characters, raising questions about whether it can be reliably distinguished from other small ornithopods. The genus is provisionally accepted as valid but its relationships remain genuinely unresolved.'
  },

  yangchuanosaurus: {
    status: 'contested',
    note: 'Two species are described from the same Shangshaximiao Formation: the smaller Y. shangyouensis (1978) and the larger Y. magnus (1983). Some researchers argue that Y. magnus may represent older growth stages of Y. shangyouensis rather than a biologically distinct species, as the anatomical differences between them are consistent with ontogenetic variation. Most current workers provisionally maintain both species, but the validity of Y. magnus as a separate taxon has not been resolved. Additionally, the relationship of Yangchuanosaurus to the closely related Sinraptor from the same formation has been debated.'
  },

  abelisaurus: {
    status: 'contested',
    note: 'Abelisaurus comahuensis is known exclusively from an incomplete skull — no postcranial skeleton has ever been recovered. Several researchers have argued that the known material, while showing abelisaurid features, is insufficient for confident diagnosis as a distinct genus separate from other Gondwanan abelisaurids of similar age. Most workers accept Abelisaurus as valid (it is the type genus of Abelisauridae), but the incompleteness of the holotype means its detailed anatomy and precise phylogenetic position within abelisaurids remain poorly constrained.'
  },

  avimimus: {
    status: 'contested',
    note: 'The phylogenetic placement of Avimimus within Oviraptorosauria has shifted substantially between published analyses. The claimed "quill attachment ridge" on the ulna — originally cited as the first evidence of wing feathers in a non-avian dinosaur — has been reinterpreted by some researchers as a muscular attachment scar or taphonomic feature rather than a genuine quill knob, meaning the feather evidence is less secure than initially proposed. Additionally, some anatomical features of the type specimens are ambiguous due to incomplete preservation. The genus is generally accepted but several key anatomical claims remain disputed.'
  },

  concavenator: {
    status: 'contested',
    note: 'Concavenator corcovatus is well-established as a distinct and valid genus, but one specific interpretation has been contested: Ortega and colleagues (2010) described small bumps on the ulna as quill knobs (calamus scars) homologous to those anchoring wing feathers in modern birds, which would extend integumentary evidence for proto-feathers into Carcharodontosauridae. This interpretation has been disputed by other researchers who argue the bumps are consistent with normal muscular attachment scars, pathological features, or taphonomic artefacts — and that they lack the consistent size, shape and spacing seen in genuine avian quill knobs. The quill node hypothesis remains unverified.'
  },
}; window.VALIDITY_STATUS = VALIDITY_STATUS;
