  polacanthus: { formations:'Wessex Formation, Isle of Wight, England; possibly also Wadhurst Clay, Sussex', material:'A partial skeleton with armour plates and spines but lacking a skull.', completeness:'Partial — no skull known', paleo:'Early Cretaceous deltaic and floodplain environments of southern England.', evidence:'The distinctive lateral blade-like spines and dorsal armour pattern identify it as a basal ankylosaur distinct from the fused-club-bearing ankylosaurids.' },
