  saurolophus: { formations:'Horseshoe Canyon Formation, Alberta, Canada; Nemegt Formation, Mongolia', material:'Skulls and skeletons from both North America and Asia.', completeness:'Well represented on two continents', paleo:'Latest Cretaceous coastal plain and floodplain environments of both western North America and Mongolia.', evidence:'The solid bony crest and hadrosaur skeletal anatomy are documented; the cross-continental range is biogeographically significant.' },
  scelidosaurus: { formations:'Charmouth Mudstone Formation, Dorset, England', material:'Several partial to near-complete articulated skeletons.', completeness:'Good for an early thyreophoran', paleo:'Early Jurassic nearshore marine environment — the Dorset specimens were apparently washed out to sea after death.', evidence:'Rows of scutes along the back and primitive thyreophoran skeletal features document its position near the base of the armoured dinosaur radiation.' },
  sinosauropteryx: { formations:'Yixian Formation, Liaoning, China', material:'Several complete or near-complete specimens with feather impressions and stomach contents.', completeness:'Exceptional — feathers and diet directly preserved', paleo:'Early Cretaceous lake and forest ecosystem of northeastern China.', evidence:'Filamentous feather impressions and melanosome analysis allowed colour reconstruction; stomach contents preserve lizard and mammal prey.' },
